"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useLivingShader, type FieldMotionProps } from "@/lib/cojeev/living-shader";

export type ContourFieldProps = Omit<React.ComponentProps<"div">, "children" | "ref"> & FieldMotionProps;

/** Quiet topographic lines on the inherited paper. Decorative, with a still fallback. */
export function ContourField({ speed = 1, intensity = 1, tone = "cool", paused = false, className, style, ...props }: ContourFieldProps) {
  const { host: hostRef, canvas: canvasRef, status, tone: safeTone, intensity: safeIntensity, moving } = useLivingShader("contour", { speed, intensity, tone, paused });
  return (
    <div {...props} ref={hostRef} data-slot="contour-field" data-tone={safeTone} data-renderer={status} data-moving={moving ? "true" : "false"} className={cn("v-contour-field", className)} style={{ ...style, "--field-intensity": safeIntensity } as React.CSSProperties} aria-hidden="true" inert>
      <span data-slot="field-fallback" />
      <canvas ref={canvasRef} data-slot="field-canvas" aria-hidden="true" />
    </div>
  );
}

"use client";

import * as React from "react";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";

export type FieldTone = "balanced" | "warm" | "cool";
export type LivingShaderKind = "pigment" | "contour";
export type LivingShaderStatus = "pending" | "webgl" | "fallback" | "lost";
export type FieldMotionProps = {
  /** Relative pace, from 0 (still) to 3. */
  speed?: number;
  /** Color and relief strength, from 0 to 2. */
  intensity?: number;
  /** Accent selection from the inherited Cojeev theme. */
  tone?: FieldTone;
  /** Freeze the current artwork without removing it. */
  paused?: boolean;
};

function finite(value: number | undefined, fallback: number, min: number, max: number) {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

export function normalizeShaderMotion(speed?: number, intensity?: number) {
  return { speed: finite(speed, 1, 0, 3), intensity: finite(intensity, 1, 0, 2) };
}

/** A large retina hero must not allocate an unbounded drawing buffer. */
export function shaderResolution(cssWidth: number, cssHeight: number, deviceRatio: number) {
  if (cssWidth <= 0 || cssHeight <= 0) return { width: 1, height: 1 };
  const width = finite(cssWidth, 1, 1, 1e7);
  const height = finite(cssHeight, 1, 1, 1e7);
  const ratio = finite(deviceRatio, 1, 1, 2);
  const scale = Math.min(ratio, 4096 / width, 4096 / height, Math.sqrt(2_000_000 / (width * height)));
  return { width: Math.max(1, Math.floor(width * scale)), height: Math.max(1, Math.floor(height * scale)) };
}

const vertexSource = `
attribute vec2 aPosition;
void main() { gl_Position = vec4(aPosition, 0.0, 1.0); }
`;

// Original Cojeev field functions: analytic color densities and topographic bands.
// No framebuffer simulation, DOM capture, texture assets, or third-party shader code.
const fragmentSource = `
precision mediump float;
uniform vec2 uSize;
uniform float uTime;
uniform float uIntensity;
uniform float uKind;
uniform vec3 uPaper;
uniform vec3 uA;
uniform vec3 uB;
uniform vec3 uC;

float mound(vec2 p, vec2 center, vec2 stretch) {
  vec2 d = (p - center) * stretch;
  return exp(-dot(d, d));
}

void main() {
  vec2 uv = gl_FragCoord.xy / uSize;
  float aspect = uSize.x / max(uSize.y, 1.0);
  vec2 p = vec2((uv.x - 0.5) * min(aspect, 2.5), uv.y - 0.5);
  float t = uTime * 0.16;
  vec2 drift = vec2(sin(t * 0.71), cos(t * 0.53)) * 0.12;
  vec2 folded = p + vec2(sin(p.y * 5.7 + t), cos(p.x * 4.1 - t * 0.8)) * 0.09;
  float a = mound(folded, vec2(-0.43, 0.16) + drift, vec2(1.8, 2.8));
  float b = mound(folded, vec2(0.40, -0.23) - drift * 0.8, vec2(2.1, 2.3));
  float c = mound(folded, vec2(0.05, 0.38) + drift.yx * 0.6, vec2(2.9, 1.9));
  vec3 color = uPaper;
  if (uKind < 0.5) {
    float wash = sin(folded.x * 10.0 + folded.y * 7.0 + t * 0.7) * 0.08;
    color = mix(color, uA, smoothstep(0.07, 0.94, a + wash) * 0.70);
    color = mix(color, uB, smoothstep(0.05, 0.90, b - wash) * 0.65);
    color = mix(color, uC, smoothstep(0.08, 0.94, c) * 0.40);
    float edge = exp(-abs(a - 0.42) * 35.0) * 0.035;
    color = mix(color, uA, edge);
  } else {
    float height = a * 1.25 + b * 0.92 + c * 0.55;
    height += sin(folded.x * 4.5 - folded.y * 3.0 + t * 0.3) * 0.13;
    float phase = height * 13.0;
    float distanceToLine = abs(fract(phase) - 0.5);
    float line = 1.0 - smoothstep(0.018, 0.07, distanceToLine);
    float broadLine = 1.0 - smoothstep(0.10, 0.18, distanceToLine);
    vec3 terrain = mix(uA, uB, smoothstep(0.2, 1.5, height));
    color = mix(uPaper, terrain, 0.10 + height * 0.07);
    color = mix(color, terrain, broadLine * 0.16 + line * 0.38);
    color = mix(color, uC, line * smoothstep(0.8, 1.8, height) * 0.24);
  }
  float fiber = sin(gl_FragCoord.x * 1.37 + gl_FragCoord.y * 2.17) * 0.003;
  color = mix(uPaper, color, min(uIntensity, 1.0));
  color = mix(color, color * 0.94, max(uIntensity - 1.0, 0.0));
  gl_FragColor = vec4(clamp(color + fiber * min(uIntensity, 1.0), 0.0, 1.0), 1.0);
}
`;

type ShaderOptions = ReturnType<typeof normalizeShaderMotion> & { tone: FieldTone; visible: boolean; moving: boolean };
export type LivingShader = { update: (options: ShaderOptions) => void; dispose: () => void };

/** Owns one GPU program and its complete context, resize, theme and frame lifecycle. */
export function createLivingShader(
  canvas: HTMLCanvasElement,
  host: HTMLElement,
  kind: LivingShaderKind,
  onStatus: (status: LivingShaderStatus) => void,
): LivingShader {
  let gl: WebGLRenderingContext | null = null;
  let program: WebGLProgram | null = null;
  let buffer: WebGLBuffer | null = null;
  const shaders: WebGLShader[] = [];
  let locations: Record<string, WebGLUniformLocation | null> = {};
  let disposed = false, lost = false, failed = false, frame = 0, previous = 0, elapsed = 0;
  let options: ShaderOptions = { speed: 1, intensity: 1, tone: "balanced", visible: false, moving: false };
  let themeDirty = true, sizeDirty = true, announced = false;
  const colors = document.createElement("canvas");
  colors.width = colors.height = 1;
  const colorContext = colors.getContext("2d", { willReadFrequently: true });

  function cancel() {
    if (frame) cancelAnimationFrame(frame);
    frame = 0;
    previous = 0;
  }
  function release() {
    if (gl && !lost) {
      if (buffer) gl.deleteBuffer(buffer);
      if (program) gl.deleteProgram(program);
      for (const shader of shaders) gl.deleteShader(shader);
    }
    buffer = null; program = null; shaders.length = 0; locations = {};
  }
  function unavailable() {
    cancel(); release(); failed = true; onStatus("fallback");
  }
  function compile(type: number, source: string) {
    const shader = gl!.createShader(type);
    if (!shader) throw new Error("Shader allocation failed");
    shaders.push(shader);
    gl!.shaderSource(shader, source); gl!.compileShader(shader);
    if (!gl!.getShaderParameter(shader, gl!.COMPILE_STATUS)) throw new Error("Shader compilation failed");
    return shader;
  }
  function initialize() {
    if (disposed || lost || failed || program) return;
    try {
      gl = canvas.getContext("webgl", { alpha: false, antialias: false, depth: false, stencil: false, powerPreference: "low-power" });
      if (!gl || gl.isContextLost()) throw new Error("WebGL unavailable");
      program = gl.createProgram();
      if (!program) throw new Error("Program allocation failed");
      gl.attachShader(program, compile(gl.VERTEX_SHADER, vertexSource));
      gl.attachShader(program, compile(gl.FRAGMENT_SHADER, fragmentSource));
      gl.linkProgram(program);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error("Program link failed");
      buffer = gl.createBuffer();
      if (!buffer) throw new Error("Buffer allocation failed");
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
      gl.useProgram(program);
      const position = gl.getAttribLocation(program, "aPosition");
      gl.enableVertexAttribArray(position);
      gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
      for (const name of ["uSize", "uTime", "uIntensity", "uKind", "uPaper", "uA", "uB", "uC"]) locations[name] = gl.getUniformLocation(program, name);
      themeDirty = sizeDirty = true;
      announced = false;
    } catch { unavailable(); }
  }
  function color(value: string, fallback: string) {
    if (!colorContext) return [0.8, 0.8, 0.8];
    colorContext.clearRect(0, 0, 1, 1);
    colorContext.fillStyle = fallback;
    colorContext.fillStyle = value || fallback;
    colorContext.fillRect(0, 0, 1, 1);
    const pixel = colorContext.getImageData(0, 0, 1, 1).data;
    return [pixel[0] / 255, pixel[1] / 255, pixel[2] / 255];
  }
  function repaintTheme() {
    const css = getComputedStyle(host);
    const accents = options.tone === "warm" ? ["pink", "yellow", "olive"] : options.tone === "cool" ? ["blue", "olive", "pink"] : ["pink", "blue", "yellow"];
    const tokens = ["--v-paper", ...accents.map(name => `--v-${name}`)];
    const defaults = ["#fbf4e6", "#f5b8db", "#b6caeb", "#f5d867"];
    ["uPaper", "uA", "uB", "uC"].forEach((name, index) => gl!.uniform3fv(locations[name], color(css.getPropertyValue(tokens[index]).trim(), defaults[index])));
    themeDirty = false;
  }
  function canDraw() { return !disposed && !lost && !failed && options.visible && !document.hidden; }
  function request() { if (canDraw() && !frame) frame = requestAnimationFrame(draw); }
  function draw(time: number) {
    frame = 0;
    if (!canDraw()) { previous = 0; return; }
    initialize();
    if (!gl || !program || failed) return;
    try {
      if (sizeDirty) {
        const { width, height } = shaderResolution(host.clientWidth, host.clientHeight, window.devicePixelRatio);
        if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
        gl.viewport(0, 0, width, height);
        gl.uniform2f(locations.uSize, width, height);
        sizeDirty = false;
      }
      if (themeDirty) repaintTheme();
      const delta = previous ? Math.min(Math.max(0, (time - previous) / 1000), 0.05) : 0;
      if (options.moving) elapsed += delta * options.speed;
      previous = time;
      gl.uniform1f(locations.uTime, elapsed);
      gl.uniform1f(locations.uIntensity, options.intensity);
      gl.uniform1f(locations.uKind, kind === "pigment" ? 0 : 1);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      if (!announced) { announced = true; onStatus("webgl"); }
      if (options.moving && options.speed > 0 && options.intensity > 0) request();
      else previous = 0;
    } catch { unavailable(); }
  }
  function resize() { sizeDirty = true; request(); }
  function appearance() { themeDirty = true; request(); }
  function visibility() { cancel(); if (!document.hidden) request(); }
  function onLost(event: Event) {
    event.preventDefault(); lost = true; cancel(); release(); onStatus("lost");
  }
  function onRestored() {
    if (disposed) return;
    lost = false; failed = false; gl = null; themeDirty = sizeDirty = true; request();
  }
  canvas.addEventListener("webglcontextlost", onLost);
  canvas.addEventListener("webglcontextrestored", onRestored);
  document.addEventListener("visibilitychange", visibility);
  window.addEventListener("resize", resize, { passive: true });
  window.addEventListener("cojeev:appearancechange", appearance);
  const resizeObserver = new ResizeObserver(resize); resizeObserver.observe(host);
  // Theme scopes can be nested; observe the actual ancestry, not only :root.
  const themeObserver = new MutationObserver(appearance);
  let ancestor: HTMLElement | null = host;
  while (ancestor) { themeObserver.observe(ancestor, { attributes: true, attributeFilter: ["style", "class", "data-mode", "data-theme"] }); ancestor = ancestor.parentElement; }

  return {
    update(next) {
      if (disposed) return;
      const motion = normalizeShaderMotion(next.speed, next.intensity);
      themeDirty ||= options.tone !== next.tone;
      const changed = options.speed !== motion.speed || options.intensity !== motion.intensity || options.tone !== next.tone || options.visible !== next.visible || options.moving !== next.moving;
      options = { ...next, ...motion };
      if (!options.visible || !options.moving) cancel();
      if (changed || themeDirty || sizeDirty) request();
    },
    dispose() {
      if (disposed) return;
      disposed = true; cancel();
      canvas.removeEventListener("webglcontextlost", onLost);
      canvas.removeEventListener("webglcontextrestored", onRestored);
      document.removeEventListener("visibilitychange", visibility);
      window.removeEventListener("resize", resize);
      window.removeEventListener("cojeev:appearancechange", appearance);
      resizeObserver.disconnect(); themeObserver.disconnect(); release();
      // Releasing GPU objects is enough; forcing loss breaks React Strict Mode's
      // immediate remount on the same canvas. The browser retires detached contexts.
      gl = null;
    },
  };
}

export function useLivingShader(kind: LivingShaderKind, props: FieldMotionProps) {
  const host = React.useRef<HTMLDivElement>(null);
  const canvas = React.useRef<HTMLCanvasElement>(null);
  const renderer = React.useRef<LivingShader | null>(null);
  const [status, setStatus] = React.useState<LivingShaderStatus>("pending");
  const { enabled, inView } = useMotionVisibility(host);
  const { speed, intensity } = normalizeShaderMotion(props.speed, props.intensity);
  const tone = props.tone === "cool" || props.tone === "warm" ? props.tone : "balanced";
  const moving = enabled && !props.paused && speed > 0 && intensity > 0;

  React.useEffect(() => {
    if (!canvas.current || !host.current) return;
    renderer.current = createLivingShader(canvas.current, host.current, kind, next => setStatus(previous => previous === next ? previous : next));
    return () => { renderer.current?.dispose(); renderer.current = null; };
  }, [kind]);
  React.useEffect(() => { renderer.current?.update({ speed, intensity, tone, visible: inView, moving }); }, [speed, intensity, tone, inView, moving]);
  return { host, canvas, status, tone, intensity, moving: status === "webgl" && moving && inView };
}

"use client";
import * as React from "react";
import { getServerSettingsSnapshot, getSettingsSnapshot, subscribeSettings } from "@/lib/cojeev-motion/settings";

function subscribePreferences(listener: () => void) {
  const media = window.matchMedia("(prefers-reduced-motion: reduce)");
  media.addEventListener("change", listener);
  document.addEventListener("visibilitychange", listener);
  return () => {
    media.removeEventListener("change", listener);
    document.removeEventListener("visibilitychange", listener);
  };
}
function readPreferences() {
  return document.visibilityState === "visible" && !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}
/** A shared stillness boundary for optional landing-page effects. */
export function useMotionVisibility(ref: React.RefObject<Element | null>, mountedElement?: Element | null) {
  const { motion, flow } = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const permitted = React.useSyncExternalStore(subscribePreferences, readPreferences, () => false);
  const [inView, setInView] = React.useState(false);
  React.useEffect(() => {
    const element = mountedElement ?? ref.current;
    if (!element) { setInView(false); return; }
    const observer = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), { threshold: 0.1 });
    observer.observe(element);
    return () => observer.disconnect();
  }, [ref, mountedElement]);
  return { enabled: permitted && motion.mode !== "off" && flow.variant !== "off", inView };
}

export const RUNTIME={cfg:{rest:false,reach:true,merge:true,hold:true,jiggleOn:true,press:true,echo:false,dots:0,grain:.08,sheen:.6,curve:1.2,lobeK:130,lobeZ:1,mergeZ:.8,arcK:40,holdK:80,pressK:170,jiggle:.35,jiggleDecay:1.6,restSpeed:1,drift:1,quality:2.5},
 tier:{pill:{amp:0,reach:3,inside:1.2,press:.02},tile:{amp:0,reach:2.4,inside:1,press:.02},nav:{amp:0,reach:1.2,inside:.5,press:.008},card:{amp:0,reach:1,inside:.4,press:.004},blob:{amp:.006,reach:3,inside:1.2,press:.03}}};
/* Per-tier authoring domains live with the profile, so a slider cannot offer a value the tier cannot mean
   (the spinner's amp .14 is legitimate and must not be clamped to the pill's 3 % ceiling). */
export const DOMAIN={amp:{max:{pill:3,tile:3,nav:1,card:1,blob:8,spinner:20},min:0},reach:{max:{pill:24,tile:24,nav:12,card:12,blob:32,spinner:0},min:0},inside:{max:{pill:12,tile:12,nav:6,card:6,blob:16,spinner:0},min:0},press:{max:{pill:12,tile:12,nav:4,card:4,blob:16,spinner:0},min:0},R:{max:{pill:240,tile:240,nav:160,card:160,blob:320,spinner:0},min:0},sig:{max:{pill:120,tile:120,nav:80,card:160,blob:160,spinner:8},min:1}};
export const factoryTiers={pill:{amp:.008,reach:4,inside:2,sig:24,R:80,press:.03,lobes:0,depth:0,asym:0,spread:.55},tile:{amp:.008,reach:3.5,inside:1.6,sig:18,R:64,press:.035,lobes:0,depth:0,asym:0,spread:.55},nav:{amp:.0006,reach:3,inside:1.2,sig:24,R:64,press:.010,lobes:0,depth:0,asym:0,spread:.55},card:{amp:.0003,reach:2.5,inside:.9,sig:44,R:56,press:.004,lobes:0,depth:0,asym:0,spread:.55},blob:{amp:.012,reach:4,inside:1.8,sig:22,R:64,press:.05,lobes:0,depth:0,asym:0,spread:.55},spinner:{amp:.14,reach:0,inside:0,sig:1,R:0,press:0,lobes:0,depth:0,asym:0,spread:.55}};
export const factoryCfg={quality:2.5,grain:.12,sheen:1,curve:1,lobeK:90,lobeZ:.9,mergeZ:.62,arcK:26,holdK:55,pressK:140,jiggle:.45,jiggleDecay:1.35,restSpeed:1,drift:1,rest:true,reach:true,merge:true,hold:true,jiggleOn:true,press:true,echo:false,echoOff:6,echoScale:1.04,dots:0};


export type MorphConfig = typeof factoryCfg
export type TierName = keyof typeof factoryTiers
export type Tier = typeof factoryTiers.pill
export type ProductCategory = "buttons" | "icons" | "pills" | "cards" | "skeleton"
export type Category = ProductCategory | "nav" | "inputs" | "controls" | "surfaces"
export type MotionSettings = {v:3;mode:"off"|"subtle";cats:Record<Category,boolean>}
export type MorphProfile = {cfg:MorphConfig;TIER:Record<TierName,Tier>}
export type FlowVariant = "glide"|"stretch"|"jelly"|"comet"|"drop"|"rubber"|"pebble"|"ripple"|"halo"|"off"
export type FlowSettings = {variant:FlowVariant;hover:boolean;speed:number;intensity:number;hoverStrength:number}
export type SettingsSnapshot = Readonly<{motion:MotionSettings;flow:FlowSettings;profile:MorphProfile;authored:boolean}>
export const MOTION_KEY = "v-motion"
export const MORPH_KEY = "v-morph-cfg-v3"
export const FLOW_KEY = "v-flow-v1"
export const PRODUCT_CATEGORIES:readonly ProductCategory[] = ["buttons","icons","pills","cards","skeleton"]
export const FLOW_DEFAULTS:Readonly<FlowSettings> = Object.freeze({variant:"glide",hover:true,speed:1,intensity:1,hoverStrength:1})
export const FLOW_CHARACTERS:Record<FlowVariant,{label:string;duration:number;ease:string;land:string;glow?:string}> = {
 glide:{label:"Glide",duration:.24,ease:"cubic-bezier(.2,.8,.2,1)",land:"none"},
 stretch:{label:"Stretch",duration:.3,ease:"cubic-bezier(.3,1.15,.4,1)",land:"vf-land"},
 jelly:{label:"Jelly",duration:.5,ease:"cubic-bezier(.3,1.3,.45,1)",land:"vf-jellyx"},
 comet:{label:"Comet",duration:.34,ease:"cubic-bezier(.2,.8,.2,1)",land:"vf-land"},
 drop:{label:"Ink drop",duration:.3,ease:"cubic-bezier(.3,1.25,.4,1)",land:"vf-bloom"},
 rubber:{label:"Rubber",duration:.36,ease:"cubic-bezier(.3,1.3,.4,1)",land:"vf-land"},
 pebble:{label:"Pebble",duration:.46,ease:"cubic-bezier(.32,1.25,.42,1)",land:"vf-lean"},
 ripple:{label:"Ripple",duration:.36,ease:"cubic-bezier(.2,.8,.2,1)",land:"vf-land",glow:"vf-ring"},
 halo:{label:"Halo",duration:.4,ease:"cubic-bezier(.3,1.2,.4,1)",land:"vf-land",glow:"vf-glow"},
 off:{label:"Off",duration:0,ease:"linear",land:"none"},
}
const defaultSettings:MotionSettings={v:3,mode:"subtle",cats:{buttons:true,icons:true,pills:true,cards:false,skeleton:true,nav:false,inputs:false,controls:false,surfaces:false}}
function runtime():MorphProfile {
 const TIER=structuredClone(factoryTiers)
 for(const name of Object.keys(RUNTIME.tier) as (keyof typeof RUNTIME.tier)[]) Object.assign(TIER[name],RUNTIME.tier[name])
 return {cfg:{...factoryCfg,...RUNTIME.cfg},TIER}
}
function immutable<T>(value:T):T {
 if(value && typeof value==="object"){Object.values(value).forEach(immutable);Object.freeze(value)}
 return value
}
const serverSnapshot:SettingsSnapshot=immutable({motion:structuredClone(defaultSettings),flow:{...FLOW_DEFAULTS},profile:runtime(),authored:false})
let settings=structuredClone(defaultSettings), profile=runtime(), flow={...FLOW_DEFAULTS}, authored=false, loaded=false
let snapshot=serverSnapshot
const listeners=new Set<()=>void>()
let releaseEvents:undefined|(()=>void), dispatching=false
function storage(){try{return typeof window==="undefined"?null:window.localStorage}catch{return null}}
function parse(key:string):unknown {try{return JSON.parse(storage()?.getItem(key)||"null")}catch{return null}}
function record(value:unknown):value is Record<string,unknown>{return !!value&&typeof value==="object"&&!Array.isArray(value)}
function mergeProfile(value:unknown,base:MorphProfile,strict=false):MorphProfile {
 if(!record(value)||(!record(value.cfg)&&!record(value.TIER)))throw new Error("Profile must contain a cfg or TIER object.")
 const next=structuredClone(base)
 if(record(value.cfg)) for(const key of Object.keys(next.cfg) as (keyof MorphConfig)[]){
  const v=value.cfg[key];if(v===undefined)continue
  if(typeof v!==typeof next.cfg[key]||(typeof v==="number"&&!Number.isFinite(v))){if(strict)throw new Error(`Invalid cfg.${key}: expected a finite ${typeof next.cfg[key]}.`);continue}
  Object.assign(next.cfg,{[key]:v})
 }
 if(record(value.TIER))for(const name of Object.keys(next.TIER) as TierName[]){const saved=value.TIER[name];if(!record(saved))continue
  for(const key of Object.keys(next.TIER[name]) as (keyof Tier)[]){const v=saved[key];if(v===undefined)continue
   if(typeof v!=="number"||!Number.isFinite(v)){if(strict)throw new Error(`Invalid TIER.${name}.${key}: expected a finite number.`);continue}
   next.TIER[name][key]=v
  }
 }
 return next
}
function normalizeFlow(value:unknown):FlowSettings {
 const v=record(value)?value:{},number=(key:string,fallback:number,min:number)=>typeof v[key]==="number"&&Number.isFinite(v[key])?Math.max(min,v[key] as number):fallback
 return {variant:typeof v.variant==="string"&&Object.hasOwn(FLOW_CHARACTERS,v.variant)?v.variant as FlowVariant:"glide",hover:typeof v.hover==="boolean"?v.hover:true,speed:number("speed",1,.25),intensity:number("intensity",1,0),hoverStrength:number("hoverStrength",1,0)}
}
export function flowToken(name:string,fallback:string,el?:Element){try{return getComputedStyle(el??document.documentElement).getPropertyValue(name).trim()||fallback}catch{return fallback}}
export function flowTokenMs(name:string,fallback:number,el?:Element){const v=flowToken(name,"",el),n=parseFloat(v);return Number.isFinite(n)?n*(v.endsWith("ms")?1:1000):fallback}
export function applyFlowSettings(){
 if(typeof document==="undefined")return
